 private Spinner spinner(LinearLayout r,String[] values){Spinner s=new Spinner(getContext());r.addView(s,new LayoutParams(-1,dp(48)));if(r.getOrientation()==HORIZONTAL)s.setLayoutParams(new LayoutParams(dp(160),dp(48)));adapter(s,Arrays.asList(values));return s;}
