 private boolean visible(String kind,String key){return kind.equals("subjects")?Arrays.asList("subjectType","displayName","platform","profileUrl","aliases","description","identityStatus","identityBasis").contains(key):kind.equals("sources")?Arrays.asList("title","text","sourceUrl","author","publishedAt","contentRole","evidenceLevel").contains(key):Arrays.asList("title","versionLabel","conditions","steps","evidenceQuote","counterexamples","invalidations","interpretation").contains(key);}
 private void load(JSONObject input)throws Exception{PersonMethodModel.need(input.length()>0,"版本不存在，未替换草稿");baseline=new JSONObject(input.toString());draft=new JSONObject(input.toString());String k=input.getString("kind");subjectId=k.equals("subjects")?input.getString("entityId"):input.getString("subjectId");references=input.has("sourceRefs")?new JSONArray(input.getJSONArray("sourceRefs").toString()):new JSONArray();filling=true;try{for(String key:NAMES){String text=input.optString(key);if(key.equals("aliases")){List<String> aliases=new ArrayList<>();JSONArray a=input.optJSONArray("aliases");if(a!=null)for(int i=0;i<a.length();i++)aliases.add(a.getString(i));text=String.join("\n",aliases);}if(k.equals("sources")&&Arrays.asList("sourceUrl","author","publishedAt","contentRole","evidenceLevel").contains(key))text=input.getJSONObject("legacyOriginal").optString(key);fields.get(key).setText(text);fields.get(key).setVisibility(visible(k,key)?VISIBLE:GONE);labels.get(key).setVisibility(visible(k,key)?VISIBLE:GONE);}}finally{filling=false;}refArea.setVisibility(k.equals("methods")?VISIBLE:GONE);renderReferences();JSONObject owner=k.equals("subjects")?input:k.equals("methods")?input.getJSONObject("subjectRef").getJSONObject("originalRecord"):store.latest("subjects",subjectId);identity.setText((k.equals("subjects")?"当前编辑对象":k.equals("sources")?"当前编辑来源版本":"当前编辑人工方法版本")+" · 关联对象 "+owner.optString("displayName","未知 / 未命名")+" · "+input.optString("id")+"\n对象身份 "+subjectId+"；身份与有效性待独立核实");dirty=false;show(form);schedule();}
 private void newRecord()throws Exception{String k=kind(),entity=UUID.randomUUID().toString();JSONObject r=new JSONObject().put("kind",k).put("entityId",entity).put("id","").put("parentId","").put("savedAt","");if(k.equals("subjects")){r.put("subjectType","person").put("identityStatus","unverified").put("aliases",new JSONArray());for(String f:new String[]{"displayName","platform","profileUrl","description","identityBasis"})r.put(f,"");}else{PersonMethodModel.need(!subjectId.isEmpty(),"先在对象页选择所属人物、书籍或方法");JSONObject owner=store.latest("subjects",subjectId);PersonMethodModel.need(owner.length()>0&&!owner.optBoolean("archived"),"所属对象不存在或已归档");r.put("subjectId",subjectId).put("title","");if(k.equals("sources"))r.put("text","").put("legacyOriginal",new JSONObject().put("id",entity).put("content","").put("contentRole","manual_note").put("evidenceLevel","commentary"));else{JSONObject s=store.latest("subjects",subjectId);PersonMethodModel.need(s.length()>0&&!s.optBoolean("archived"),"所属对象不存在或已归档");r.put("subjectRef",PersonMethodModel.version("person-method","subjects",s.getString("id"),s)).put("sourceRefs",new JSONArray());for(String f:new String[]{"versionLabel","conditions","steps","evidenceQuote","counterexamples","invalidations","interpretation"})r.put(f,"");}}load(r);baseline=new JSONObject();dirty=false;}
 private void sync()throws Exception{if(draft.length()==0)return;String k=draft.getString("kind");for(String key:NAMES)if(visible(k,key)){String text=fields.get(key).getText().toString();if(key.equals("aliases")){JSONArray a=new JSONArray();for(String line:text.split("\n"))if(!line.trim().isEmpty())a.put(line.trim());draft.put(key,a);}else if(k.equals("sources")&&Arrays.asList("sourceUrl","author","publishedAt","contentRole","evidenceLevel").contains(key))draft.getJSONObject("legacyOriginal").put(key,text);else draft.put(key,text);}if(k.equals("methods"))draft.put("sourceRefs",new JSONArray(references.toString()));}
 private void save(boolean archive)throws Exception{sync();JSONObject r=new JSONObject(draft.toString());PersonMethodModel.need(r.length()>0,"没有编辑草稿");r.put("id",r.getString("entityId")+"@"+UUID.randomUUID()).put("parentId",baseline.optString("id")).put("savedAt",java.time.Instant.now().toString());if(archive)r.put("archived",true);if(r.getString("kind").equals("sources")){JSONObject old=r.getJSONObject("legacyOriginal");old.put("content",r.getString("text")).put("title",r.getString("title")).put("manualRevision",true);old.remove("text");old.remove("transcript");}load(store.append(r,baseline));refresh();status.setText("已保存不可变版本；身份与方法有效性仍需独立验证");persist();}
 private void addReference()throws Exception{PersonMethodModel.need("methods".equals(draft.optString("kind")),"只有人工方法可关联来源");int i=refPicker.getSelectedItemPosition();PersonMethodModel.need(i>=0&&i<options.size(),"没有可关联的完整来源版本");JSONObject ref=options.get(i);PersonMethodModel.validateVersion(ref);for(int j=0;j<references.length();j++)if(PersonMethodModel.canonical(ref).equals(PersonMethodModel.canonical(references.get(j))))return;PersonMethodModel.need(references.length()<100,"最多100个来源版本");references.put(new JSONObject(ref.toString()));sync();dirty=true;renderReferences();schedule();}
 private void renderReferences()throws Exception{List<String> titles=new ArrayList<>();for(int i=0;i<references.length();i++){JSONObject r=references.getJSONObject(i);titles.add(r.getString("namespace")+"/"+r.getString("kind")+" · "+r.getString("id")+" · "+r.getString("fingerprint"));}refsLabel.setText("冻结来源版本 "+references.length()+"；证据匹配仅核对引用字串，不确认作者或有效性");adapter(boundPicker,titles);}
 private void showOriginal(JSONObject ref)throws Exception{PersonMethodModel.validateVersion(ref);readerRef=new JSONObject(ref.toString());JSONObject raw=ref.getJSONObject("originalRecord");reader.setText("完整版本 "+ref.getString("id")+"\n指纹 "+ref.getString("fingerprint")+"\n\n"+(PersonMethodModel.body(raw).isEmpty()?"原记录未提供正文或转写；摘要与旧分析仅作为原记录读取":PersonMethodModel.body(raw))+"\n\n完整原记录（含出处、旧分析与未知字段）\n"+raw.toString(2));show(reader);}
 private void locate()throws Exception{PersonMethodModel.need(!dirty,"草稿尚未保存，未离开当前编辑");JSONObject ref;if(reader.getVisibility()==VISIBLE)ref=readerRef;else{int i=boundPicker.getSelectedItemPosition();PersonMethodModel.need(i>=0&&i<references.length(),"先选择已关联的来源版本");ref=references.getJSONObject(i);}PersonMethodModel.validateVersion(ref);if(ref.getString("namespace").equals("person-method")){JSONObject current=store.get(ref.getString("kind"),ref.getString("id"));PersonMethodModel.need(PersonMethodModel.canonical(current).equals(PersonMethodModel.canonical(ref.getJSONObject("originalRecord"))),"来源版本已变化或不存在；冻结原文仍保留");showOriginal(ref);}else{boolean current=false;if(versions!=null){JSONArray all=versions.read();for(int i=0;i<all.length();i++)current|=PersonMethodModel.canonical(ref).equals(PersonMethodModel.canonical(all.get(i)));}PersonMethodModel.need(current&&opener!=null,"当前完整来源版本无法匹配，未按标题定位");persist();opener.open(new JSONObject(ref.toString()));}}
 private String importSummary(JSONObject input,JSONObject preview)throws Exception{StringBuilder text=new StringBuilder("导入预览：仅确认后写入；同名不合并，冲突保留已有。\n旧作者、证据级别、信心与营销描述是原记录，不代表独立确认。\n");JSONArray subjects=input.getJSONArray("subjects");for(int i=0;i<subjects.length();i++){JSONObject r=subjects.getJSONObject(i);text.append("\n对象 · ").append(r.getString("subjectType")).append(" · ").append(r.getString("displayName")).append(" · ").append(r.getString("platform")).append("\n").append(r.getString("id")).append("\n出处 ").append(r.getString("profileUrl")).append("\n记录指纹 ").append(r.getString("recordRevision")).append('\n');}JSONArray sources=input.getJSONArray("sources");for(int i=0;i<sources.length();i++){JSONObject r=sources.getJSONObject(i),old=r.getJSONObject("legacyOriginal");text.append("\n来源 · ").append(r.getString("title")).append("\n").append(r.getString("id")).append("\n所属对象 ").append(r.getString("subjectId")).append("\n链接 ").append(old.optString("sourceUrl")).append("\n旧署名 ").append(old.optString("author")).append("\n旧发布时间 ").append(old.optString("publishedAt")).append("\n旧角色 / 级别 ").append(old.optString("contentRole")).append(" / ").append(old.optString("evidenceLevel")).append("\n完整正文 ").append(r.getString("text").length()).append(" UTF-16字符；全部原记录与未知字段保留\n指纹 ").append(r.getString("recordRevision")).append('\n');}JSONArray methods=input.getJSONArray("methods");for(int i=0;i<methods.length();i++){JSONObject r=methods.getJSONObject(i);text.append("\n人工方法 · ").append(r.getString("title")).append(" · ").append(r.getString("versionLabel")).append("\n").append(r.getString("id")).append("\n对象版本 ").append(r.getJSONObject("subjectRef").getString("id")).append("\n状态 ").append(r.getJSONObject("assessment").getString("status")).append('\n');JSONArray refs=r.getJSONArray("sourceRefs");for(int j=0;j<refs.length();j++){JSONObject ref=refs.getJSONObject(j);text.append("关联 ").append(ref.getString("namespace")).append('/').append(ref.getString("kind")).append(" · ").append(ref.getString("id")).append(" · ").append(ref.getString("fingerprint")).append('\n');}}JSONArray conflicts=preview.getJSONArray("conflicts");for(int i=0;i<conflicts.length();i++)text.append("\n保留已有冲突版本 · ").append(conflicts.getString(i));return text.toString();}
 void previewImport(String text)throws Exception{pending=new JSONObject();pendingBaseline=new JSONObject();JSONObject input=PersonMethodModel.decode(text);PersonMethodModel.need(input.toString().getBytes(StandardCharsets.UTF_8).length<=32*1024*1024,"转换后超过32MiB，请拆分；未生成不可确认预览");JSONObject current=store.backup(),p=PersonMethodModel.preview(input,current);pending=input;pendingBaseline=current;readerRef=new JSONObject();reader.setText(importSummary(input,p));show(reader);status.setText("预览：新增"+p.getInt("added")+"，完全重复"+p.getInt("duplicate")+"，冲突"+p.getJSONArray("conflicts").length()+"（保留已有）；仅确认后写入");persist();}
 void confirmImport()throws Exception{PersonMethodModel.need(pending.length()>0,"没有待确认导入");store.merge(pending,pendingBaseline);pending=new JSONObject();pendingBaseline=new JSONObject();refresh();show(list);status.setText("导入完成，原草稿与旧版本保留；旧营销描述未确认");persist();}
 void cancelImport()throws Exception{pending=new JSONObject();pendingBaseline=new JSONObject();show(form);status.setText("已取消预览，未写入资料库");persist();}
 private JSONObject state()throws Exception{sync();return new JSONObject().put("schema","person-method-view/v1").put("baseline",baseline).put("draft",draft).put("references",references).put("subjectId",subjectId).put("dirty",dirty).put("mode",mode.getSelectedItemPosition()).put("type",typeFilter.getSelectedItemPosition()).put("review",reviewFilter.getSelectedItemPosition()).put("search",search.getText().toString()).put("pending",pending).put("pendingBaseline",pendingBaseline);}
 private void persist()throws Exception{FileOutputStream out=null;try{out=stateFile.startWrite();out.write(state().toString().getBytes(StandardCharsets.UTF_8));stateFile.finishWrite(out);}catch(Exception e){if(out!=null)stateFile.failWrite(out);throw e;}}
